CREATE TABLE users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE records (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), file_name text NOT NULL, object_key text UNIQUE NOT NULL, sha256 text NOT NULL, byte_length bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE report_jobs (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), state text NOT NULL DEFAULT 'PENDING' CHECK (state IN ('PENDING','COMPLETED')), output text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE controls (id integer PRIMARY KEY CHECK(id=1), jobs_paused boolean NOT NULL DEFAULT true, maintenance boolean NOT NULL DEFAULT false);
INSERT INTO controls(id) VALUES(1);
CREATE TABLE scheduled_runs (occurrence_at timestamptz PRIMARY KEY, finished_at timestamptz NOT NULL DEFAULT now(), expired_sessions_removed integer NOT NULL);
CREATE INDEX sessions_owner ON sessions(owner_id);
CREATE INDEX records_owner ON records(owner_id);
CREATE INDEX documents_owner ON documents(owner_id);
CREATE INDEX pending_report_jobs ON report_jobs(created_at) WHERE state='PENDING';
